impl TryFrom<u32> for WARNcode {
    type Error = u32;
    fn try_from(v: u32) -> Result<Self, u32> {
    match v {
            0x0011A800 => Ok(WARNcode::SUCS_MODE_INVALID),
            0x0011A801 => Ok(WARNcode::SUCS_MODE_ALREADY_ACTIVE),
            0x0011A802 => Ok(WARNcode::SUCS_PLUGIN_INVALID_BLOB),
            0x0011A803 => Ok(WARNcode::SUCS_PLUGIN_DUPLICATE_ID),
            0x0011A804 => Ok(WARNcode::SUCS_PLUGIN_STAGING_FULL),
            0x0011A805 => Ok(WARNcode::SUCS_PLUGIN_NOT_OWFS),
            0x0011A806 => Ok(WARNcode::SUCS_PLUGIN_MOUNT_FAILED),
            0x0011A807 => Ok(WARNcode::SUCS_PLUGIN_BUFFER_OVERFLOW),
            0x0011A808 => Ok(WARNcode::SUCS_PLUGIN_RANGE_COLLISION),
            0x0011A809 => Ok(WARNcode::SUCS_PLUGIN_CHECKSUM_MISMATCH),
            0x0011A80A => Ok(WARNcode::SUCS_KEY_INVALID),
            0x0011A900 => Ok(WARNcode::OWFS_VOLUME_DIRTY),
            0x0011A901 => Ok(WARNcode::OWFS_VOLUME_LOCKED),
            0x0011A902 => Ok(WARNcode::OWFS_WRITE_PROTECTED),
            0x0011A903 => Ok(WARNcode::OWFS_NO_FREE_BLOCKS),
            0x0011A904 => Ok(WARNcode::OWFS_NO_FREE_INODES),
            0x0011A905 => Ok(WARNcode::OWFS_CATALOG_FULL),
            0x0011A906 => Ok(WARNcode::OWFS_ACCESS_DENIED),
            0x0011A907 => Ok(WARNcode::OWFS_KEY_INVALID),
            0x0011A908 => Ok(WARNcode::OWFS_CRC_SILENT_SKIP),
            0x0011AA00 => Ok(WARNcode::USFS_VOLUME_DIRTY),
            0x0011AA01 => Ok(WARNcode::USFS_VOLUME_LOCKED),
            0x0011AA02 => Ok(WARNcode::USFS_WRITE_PROTECTED),
            0x0011AA03 => Ok(WARNcode::USFS_NO_FREE_BLOCKS),
            0x0011AA04 => Ok(WARNcode::USFS_NO_FREE_ENTRIES),
            0x0011AA05 => Ok(WARNcode::USFS_ACCESS_DENIED),
            0x0011AA06 => Ok(WARNcode::USFS_KEY_INVALID),
            0x0011AA07 => Ok(WARNcode::USFS_ENCRYPTED_UNHANDLED),
            0x0011AB00 => Ok(WARNcode::MBL_NO_GOP),
            0x0011AB01 => Ok(WARNcode::MBL_NO_BLOCK_IO),
            0x0011AB02 => Ok(WARNcode::MBL_NO_LOADED_IMAGE),
            0x0011AB03 => Ok(WARNcode::MBL_GOP_MODE_FAIL),
            0x0011AB04 => Ok(WARNcode::MBL_REMOVABLE_MEDIA),
            0x0011AB05 => Ok(WARNcode::MBL_MEDIA_NOT_PRESENT),
            0x0011AB06 => Ok(WARNcode::MBL_OWMKFS_REBOOT_REQUIRED),
            0x0011AB07 => Ok(WARNcode::MBL_PLUGIN_REBOOT_REQUIRED),
            0x0011AB08 => Ok(WARNcode::MBL_RTC_UNAVAILABLE),
            0x0011AB09 => Ok(WARNcode::MBL_KBD_UNAVAILABLE),
            0x0011AB0A => Ok(WARNcode::MBL_MENU_EMPTY),
            0x0011AB0B => Ok(WARNcode::MBL_SUTF8_NONASCII),
            _ => Err(v),
        }
    }
}

